(3397335, 471782, 2553, '<td valign="top">Wow, wow, wow!  Where is this???? What a magnificent tree, this is so cool.  Honestly I''d like a bit sharper contrast, but still I like it a lot.</td>', 'Wow, wow, wow!  Where is this???? What a magnificent tree, this is so cool.  Honestly I''d like a bit sharper contrast, but still I like it a lot.', '2007-02-23 10:04:38.000000', NULL, 1),
(3397336, 472513, 2553, '<td valign="top">Yup. One of my favs. Love your tree.</td>', 'Yup. One of my favs. Love your tree.', '2007-02-23 10:04:43.000000', NULL, 1),
(3397337, 472353, 73564, '<td valign="top">Nice picture, it would have been good even without the person, good job.</td>', 'Nice picture, it would have been good even without the person, good job.', '2007-02-23 10:05:12.000000', NULL, 1),
(3397338, 473656, 54446, '<td valign="top">Not much effort put forth.  The trees might be enjoyable, but the interior of the car gets in the way.</td>', 'Not much effort put forth.  The trees might be enjoyable, but the interior of the car gets in the way.', '2007-02-23 10:05:26.000000', NULL, 1),
(3397342, 470474, 73564, '<td valign="top">very interesting</td>', 'very interesting', '2007-02-23 10:06:20.000000', NULL, 1),
(3397343, 470580, 54446, '<td valign="top">Boards in a fence are not trees.  Probably the biggest irritation from this image is the sensor dust in the sky.</td>', 'Boards in a fence are not trees.  Probably the biggest irritation from this image is the sensor dust in the sky.', '2007-02-23 10:06:36.000000', NULL, 1),
(3397344, 473679, 52572, '<td valign="top">great shot!<br/>beautiful.</td>', 'great shot!beautiful.', '2007-02-23 10:07:08.000000', NULL, 1),
(3397345, 471000, 73564, '<td valign="top">it.</td>', 'it.', '2007-02-23 10:07:24.000000', NULL, 1),
(3397346, 472663, 54446, '<td valign="top">Horizon not level.  Trees are distant.  Hard to tell what you are trying to present.</td>', 'Horizon not level.  Trees are distant.  Hard to tell what you are trying to present.', '2007-02-23 10:07:52.000000', NULL, 1),
(3397348, 471245, 54446, '<td valign="top">Not much effort put forth on this one.</td>', 'Not much effort put forth on this one.', '2007-02-23 10:08:29.000000', NULL, 1),
(3397349, 471782, 68256, '<td valign="top">Nice Oak, reminds me of the one on the Texas A&amp;M Campus.  I wonder if you could bump contrast up in camera before shooting?  That might have helped the "flatness" of the image.  Anyway, very good composition. 6</td>', 'Nice Oak, reminds me of the one on the Texas A&M Campus.  I wonder if you could bump contrast up in camera before shooting?  That might have helped the "flatness" of the image.  Anyway, very good composition. 6', '2007-02-23 10:08:39.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3397350, 473628, 34194, '<td valign="top">similar to my submission, I like it!</td>', 'similar to my submission, I like it!', '2007-02-23 10:08:48.000000', NULL, 1),
(3397356, 472222, 54446, '<td valign="top">well, there is a tree in the dark background.  I fail to see what you are trying to present.  You''re all set if we have a snowman challenge.</td>', 'well, there is a tree in the dark background.  I fail to see what you are trying to present.  You''re all set if we have a snowman challenge.', '2007-02-23 10:10:19.000000', NULL, 1),
(3397358, 473019, 52572, '<td valign="top">beautiful capture, comp and frame shot.</td>', 'beautiful capture, comp and frame shot.', '2007-02-23 10:11:12.000000', NULL, 1),
(3397360, 470771, 54446, '<td valign="top">Some stars, some light pollution in the sky, glaring light reflecting off the trees.  It''s not a very pleasant image to view.</td>', 'Some stars, some light pollution in the sky, glaring light reflecting off the trees.  It''s not a very pleasant image to view.', '2007-02-23 10:11:50.000000', NULL, 1),
(3397362, 473239, 34194, '<td valign="top">would have been better without the car.</td>', 'would have been better without the car.', '2007-02-23 10:12:21.000000', NULL, 1),
(3397363, 470600, 54446, '<td valign="top">oof.  I don''t see anything in the image that is in focus.  I sort of like the subject, but this image suffers from camera shake.</td>', 'oof.  I don''t see anything in the image that is in focus.  I sort of like the subject, but this image suffers from camera shake.', '2007-02-23 10:12:39.000000', NULL, 1),
(3397364, 473436, 52572, '<td valign="top">awesome work.</td>', 'awesome work.', '2007-02-23 10:12:47.000000', NULL, 1),
(3397366, 473714, 34194, '<td valign="top">sharper focus would have helped tremendously</td>', 'sharper focus would have helped tremendously', '2007-02-23 10:13:51.000000', NULL, 1),
(3397367, 472523, 68256, '<td valign="top">Great job capturing detail in the trees, must have been a tough exposure.  9</td>', 'Great job capturing detail in the trees, must have been a tough exposure.  9', '2007-02-23 10:14:06.000000', NULL, 1),
(3397368, 473579, 54446, '<td valign="top">oof.  Or, it could be motion blur from wind.  Tree silhouettes are more effective if they are in focus.  Viewing this image gives me a headache, as my eyes try to bring it into focus, but without success.</td>', 'oof.  Or, it could be motion blur from wind.  Tree silhouettes are more effective if they are in focus.  Viewing this image gives me a headache, as my eyes try to bring it into focus, but without success.', '2007-02-23 10:14:22.000000', NULL, 1),
(3397373, 473661, 54446, '<td valign="top">I think the weed in front is a "Queen Anne''s Lace", but I don''t know.  I know it''s not a tree.  There is a tree in the background... blurred... due to narrow DOF.  Well, you knew this was a risk.</td>', 'I think the weed in front is a "Queen Anne''s Lace", but I don''t know.  I know it''s not a tree.  There is a tree in the background... blurred... due to narrow DOF.  Well, you knew this was a risk.', '2007-02-23 10:15:54.000000', NULL, 1),
(3397374, 473025, 68256, '<td valign="top">Wow, that is an impressive tree!  Very well captured too. 10 and a favorite!</td>', 'Wow, that is an impressive tree!  Very well captured too. 10 and a favorite!', '2007-02-23 10:16:02.000000', NULL, 1),
(3397377, 473372, 52572, '<td valign="top">woowww..<br/>love the sparkling!</td>', 'woowww..love the sparkling!', '2007-02-23 10:17:17.000000', NULL, 1),
(3397378, 471892, 54446, '<td valign="top">A fair effort, but the result is not very enjoyable.  I think it''s the overly bright sky which hurts the effect.</td>', 'A fair effort, but the result is not very enjoyable.  I think it''s the overly bright sky which hurts the effect.', '2007-02-23 10:17:17.000000', NULL, 1),
(3397380, 473195, 52572, '<td valign="top">gorgeous composition and reflection</td>', 'gorgeous composition and reflection', '2007-02-23 10:17:57.000000', NULL, 1),
(3397384, 473614, 68256, '<td valign="top">The texture in the foreground trunk really bumps this score up a lot.  Without the texture - a flat 6....with the texture - a dynamic 9.  Really, it means that much to my viewing pleasure.  Thanks.  I would love to see this worked over in advance editing.</td>', 'The texture in the foreground trunk really bumps this score up a lot.  Without the texture - a flat 6....with the texture - a dynamic 9.  Really, it means that much to my viewing pleasure.  Thanks.  I would love to see this worked over in advance editing.', '2007-02-23 10:19:47.000000', NULL, 1),
(3397387, 470264, 54446, '<td valign="top">Some blurriness in the tree... maybe wind motion.  Also, quite a few jpg artifacts around the tree edges.  And the bright spot near the upper left corner is accompanied by jpg artifacts.  The sky shows evidence of posterization.  Colors are good, but it seems to be a low quality image.  (I see the file size is only 35kb.  You lowered the jpg quality too much.  You can submit images up to 150kb.)</td>', 'Some blurriness in the tree... maybe wind motion.  Also, quite a few jpg artifacts around the tree edges.  And the bright spot near the upper left corner is accompanied by jpg artifacts.  The sky shows evidence of posterization.  Colors are good, but it seems to be a low quality image.  (I see the file size is only 35kb.  You lowered the jpg quality too much.  You can submit images up to 150kb.)', '2007-02-23 10:20:35.000000', NULL, 1),
(3397388, 472452, 31403, '<td valign="top">that''s not a tree</td>', 'that''s not a tree', '2007-02-23 10:20:38.000000', NULL, 1),
(3397391, 470455, 68256, '<td valign="top">Very effective use of fisheye...I really like it. 9  (Would love to see this with advance editing to bring out the texture and contrast)</td>', 'Very effective use of fisheye...I really like it. 9  (Would love to see this with advance editing to bring out the texture and contrast)', '2007-02-23 10:21:40.000000', NULL, 1),
(3397392, 473717, 54446, '<td valign="top">The sky is overexposed, as in detail lost in the highlights.  And, detail is lost in the shadows (where the trees are).  Unclear what you were trying to present.</td>', 'The sky is overexposed, as in detail lost in the highlights.  And, detail is lost in the shadows (where the trees are).  Unclear what you were trying to present.', '2007-02-23 10:21:46.000000', NULL, 1),
(3397395, 471212, 54446, '<td valign="top">Bright sky, but okay.  Detail lost in the shadows of the tree.  An okay silhouette, but it''s a bit gloomy with too much big branches without detail.</td>', 'Bright sky, but okay.  Detail lost in the shadows of the tree.  An okay silhouette, but it''s a bit gloomy with too much big branches without detail.', '2007-02-23 10:23:07.000000', NULL, 1),
(3397397, 473025, 31403, '<td valign="top">filters - the old fashioned photoshop!  nice creative work here</td>', 'filters - the old fashioned photoshop!  nice creative work here', '2007-02-23 10:23:38.000000', NULL, 1),
(3397398, 473436, 70369, '<td valign="top">wow... all this under minimal editing... That''s pretty awesome.</td>', 'wow... all this under minimal editing... That''s pretty awesome.', '2007-02-23 10:23:53.000000', NULL, 1),
(3397399, 470750, 54446, '<td valign="top">An artistic effort which doesn''t work too well for me.  The vertical lines seem to be tilted.  The varying light might have been very pleasant, but the blur effect makes it impossible to know.</td>', 'An artistic effort which doesn''t work too well for me.  The vertical lines seem to be tilted.  The varying light might have been very pleasant, but the blur effect makes it impossible to know.', '2007-02-23 10:24:58.000000', NULL, 1),
(3397401, 473538, 54446, '<td valign="top">While I like the vintage look and sepia treatment, I don''t think you nailed the focus.  Great subject, weak composition.</td>', 'While I like the vintage look and sepia treatment, I don''t think you nailed the focus.  Great subject, weak composition.', '2007-02-23 10:26:14.000000', NULL, 1),
(3397405, 473561, 54446, '<td valign="top">I like the title and the reference to chaos theory.  Sorry, it''s just a little soft in focus in some areas.  Detail lost in the shadows and almost lost in the brightest highlights.</td>', 'I like the title and the reference to chaos theory.  Sorry, it''s just a little soft in focus in some areas.  Detail lost in the shadows and almost lost in the brightest highlights.', '2007-02-23 10:27:53.000000', NULL, 1),
(3397407, 473563, 54446, '<td valign="top">Tough shot to get right.  The sun glare is too much.  The pine needles are too obscure and underexposed.</td>', 'Tough shot to get right.  The sun glare is too much.  The pine needles are too obscure and underexposed.', '2007-02-23 10:29:24.000000', NULL, 1),
(3397411, 473628, 54446, '<td valign="top">Well, there''s a golden pond out there.  The tree obstructs the view, which is an irritation.  A lot of black space in the lower portion of the image, which doesn''t seem to assist the image.</td>', 'Well, there''s a golden pond out there.  The tree obstructs the view, which is an irritation.  A lot of black space in the lower portion of the image, which doesn''t seem to assist the image.', '2007-02-23 10:30:56.000000', NULL, 1),
(3397414, 473278, 68256, '<td valign="top">Great use of natural framing!  Couldn''t have been better.  The diagonal log kinda kills the beauty for me though.  It is such a serene photo and then to have that breaking it up....  The lighting is absolutely wonderful.  Contrast is great and sharpness is too.  Would have been a 10 without the diagonal log, and I might still come back later and bump it to a 10 once I''m finished voting.  9</td>', 'Great use of natural framing!  Couldn''t have been better.  The diagonal log kinda kills the beauty for me though.  It is such a serene photo and then to have that breaking it up....  The lighting is absolutely wonderful.  Contrast is great and sharpness is too.  Would have been a 10 without the diagonal log, and I might still come back later and bump it to a 10 once I''m finished voting.  9', '2007-02-23 10:31:24.000000', NULL, 1),
(3397415, 470580, 73564, '<td valign="top">I''m not sure what to think.</td>', 'I''m not sure what to think.', '2007-02-23 10:31:55.000000', NULL, 1),
(3397420, 470989, 54446, '<td valign="top">One must assume there are trees inside the burlap sacks.  I guess we can use our imagination, because you didn''t show any trees in your composition.  I did score this fairly well, because your DOF is excellent.  Exposure is very good.  It''s a "think outside the box" image, which is usually punished by the punks at DPC.  (6)</td>', 'One must assume there are trees inside the burlap sacks.  I guess we can use our imagination, because you didn''t show any trees in your composition.  I did score this fairly well, because your DOF is excellent.  Exposure is very good.  It''s a "think outside the box" image, which is usually punished by the punks at DPC.  (6)', '2007-02-23 10:33:47.000000', NULL, 1),
(3397421, 472348, 73564, '<td valign="top">Nice and pretty almost a champaigne color.</td>', 'Nice and pretty almost a champaigne color.', '2007-02-23 10:33:54.000000', NULL, 1),
(3397422, 473545, 68256, '<td valign="top">I just can''t believe some of these photos, really great work.  I love the contrast of texture and light in both cloud and snow.  9</td>', 'I just can''t believe some of these photos, really great work.  I love the contrast of texture and light in both cloud and snow.  9', '2007-02-23 10:33:54.000000', NULL, 1),
(3397425, 471647, 73564, '<td valign="top">Wow that is neat!</td>', 'Wow that is neat!', '2007-02-23 10:34:46.000000', NULL, 1),
(3397426, 473013, 54446, '<td valign="top">Might work for the low key challenge.  Hard to see the trees in this one.  Interesting light. (6)</td>', 'Might work for the low key challenge.  Hard to see the trees in this one.  Interesting light. (6)', '2007-02-23 10:34:51.000000', NULL, 1),
(3397427, 473436, 67343, '<td valign="top">Great tree image love the colors and the shape of the tree.</td>', 'Great tree image love the colors and the shape of the tree.', '2007-02-23 10:35:04.000000', NULL, 1),
(3397428, 473436, 68256, '<td valign="top">10, but that green on the tree is just weird :)</td>', '10, but that green on the tree is just weird :)', '2007-02-23 10:35:14.000000', NULL, 1),
(3397429, 473666, 69102, '<td valign="top">great colors, interesting angle and perspective. becomes a landscape itself. :)</td>', 'great colors, interesting angle and perspective. becomes a landscape itself. :)', '2007-02-23 10:35:27.000000', NULL, 1),
(3397430, 473019, 69102, '<td valign="top">lovely. wonderful mood. excellently composed.</td>', 'lovely. wonderful mood. excellently composed.', '2007-02-23 10:35:32.000000', NULL, 1),
(3397431, 473025, 69102, '<td valign="top">wow. just beautiful. excellent use of a gradient filter.</td>', 'wow. just beautiful. excellent use of a gradient filter.', '2007-02-23 10:35:48.000000', NULL, 1),
(3397442, 473571, 64929, '<td valign="top">My favorite of the challenge...Bravo!  Just gorgeous! *10*</td>', 'My favorite of the challenge...Bravo!  Just gorgeous! *10*', '2007-02-23 10:42:01.000000', NULL, 1),
(3397443, 473551, 29293, '<td valign="top">nice capture</td>', 'nice capture', '2007-02-23 10:42:34.000000', NULL, 1),
