(3397448, 473571, 34194, '<td valign="top">I like the title. Nice light gradient</td>', 'I like the title. Nice light gradient', '2007-02-23 10:45:40.000000', NULL, 1),
(3397450, 473525, 68573, '<td valign="top">Very nice. I am curious to see how bright and  nice the sky would''ve looked if it was not a minimal editing challenge.</td>', 'Very nice. I am curious to see how bright and  nice the sky would''ve looked if it was not a minimal editing challenge.', '2007-02-23 10:47:17.000000', NULL, 1),
