(3397453, 470914, 29293, '<td valign="top">nice but a bit dark for me</td>', 'nice but a bit dark for me', '2007-02-23 10:47:34.000000', NULL, 1),
(3397454, 473372, 68573, '<td valign="top">Love that little starry flare , great capture</td>', 'Love that little starry flare , great capture', '2007-02-23 10:48:13.000000', NULL, 1),
