(3397495, 471551, 29293, '<td valign="top">nailed the color on this exposure for minimal that is great</td>', 'nailed the color on this exposure for minimal that is great', '2007-02-23 10:59:52.000000', NULL, 1),
(3397497, 473666, 70181, '<td valign="top">Nice macro.  It looks like some alien landscape from Star Trek.  :)</td>', 'Nice macro.  It looks like some alien landscape from Star Trek.  :)', '2007-02-23 10:59:55.000000', NULL, 1),
(3397498, 473436, 29293, '<td valign="top">i would love to know how you did this in minimal it is great</td>', 'i would love to know how you did this in minimal it is great', '2007-02-23 11:00:45.000000', NULL, 1),
(3397523, 473313, 70181, '<td valign="top">Truly beautiful.  Best photo in the entire challenge, and there were some great ones.</td>', 'Truly beautiful.  Best photo in the entire challenge, and there were some great ones.', '2007-02-23 11:10:36.000000', NULL, 1),
(3397528, 473672, 31917, '<td valign="top">love the tones and textures.  Trees can be a great subject, they just tend to get overlooked, cause people don''t look for the good compostion and angle as you have. I was disapointed until this picture. thanks. I do like it with a little more of the bottom cropped.  8</td>', 'love the tones and textures.  Trees can be a great subject, they just tend to get overlooked, cause people don''t look for the good compostion and angle as you have. I was disapointed until this picture. thanks. I do like it with a little more of the bottom cropped.  8', '2007-02-23 11:11:37.000000', NULL, 1),
(3397531, 471278, 31917, '<td valign="top">nice composition.</td>', 'nice composition.', '2007-02-23 11:13:24.000000', NULL, 1),
(3397533, 470339, 39850, '<td valign="top">6 - Really like the tree capture, especially with that cloud above, but the empty space reduced at the top (in camera, who knows) would have made a much stronger image, in my opinion.</td>', '6 - Really like the tree capture, especially with that cloud above, but the empty space reduced at the top (in camera, who knows) would have made a much stronger image, in my opinion.', '2007-02-23 11:15:11.000000', NULL, 1),
(3397537, 472513, 39850, '<td valign="top">8 - Very nice.</td>', '8 - Very nice.', '2007-02-23 11:17:20.000000', NULL, 1),
(3397564, 473436, 2223, '<td valign="top">WOW.. this is really amazing considering the minimal editing rules. Great job!</td>', 'WOW.. this is really amazing considering the minimal editing rules. Great job!', '2007-02-23 11:29:35.000000', NULL, 1),
(3397566, 470891, 32644, '<td valign="top">LOL</td>', 'LOL', '2007-02-23 11:31:02.000000', NULL, 1),
(3397572, 470750, 39850, '<td valign="top">4 - Like the concept, just wish more trees were discernible.</td>', '4 - Like the concept, just wish more trees were discernible.', '2007-02-23 11:32:50.000000', NULL, 1),
(3397580, 470889, 65234, '<td valign="top">Pretty scene; a little dark.</td>', 'Pretty scene; a little dark.', '2007-02-23 11:35:33.000000', NULL, 1),
(3397584, 472052, 65234, '<td valign="top">Is that car parked on a frozen lake?!  Interesting shape to the tree and nicely composed.</td>', 'Is that car parked on a frozen lake?!  Interesting shape to the tree and nicely composed.', '2007-02-23 11:36:46.000000', NULL, 1),
(3397586, 472933, 65234, '<td valign="top">Oh, that''s cute :-)  Nice exposure, especially considering the shadows and lights you had to try and get detail in.</td>', 'Oh, that''s cute :-)  Nice exposure, especially considering the shadows and lights you had to try and get detail in.', '2007-02-23 11:38:04.000000', NULL, 1),
