(3398256, 473341, 3102, '<td valign="top">Too bad this is rotated to the left the way it is.  A vertical crop (eliminating some dead space on the left and right), and leveled out a bit, and this could have been a ribbon contender!</td>', 'Too bad this is rotated to the left the way it is.  A vertical crop (eliminating some dead space on the left and right), and leveled out a bit, and this could have been a ribbon contender!', '2007-02-23 14:41:25.000000', NULL, 1),
(3398267, 473262, 69387, '<td valign="top">I like the mysterious theme of this shot. I also like how there''s just little light coming out through the trees.</td>', 'I like the mysterious theme of this shot. I also like how there''s just little light coming out through the trees.', '2007-02-23 14:43:10.000000', NULL, 1),
