INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3398358, 473655, 43774, '<td valign="top">Very nice, great scene, seems tilted just a bit</td>', 'Very nice, great scene, seems tilted just a bit', '2007-02-23 15:01:52.000000', NULL, 1),
(3398359, 471647, 29013, '<td valign="top">the trees at the bottom right are distracting.</td>', 'the trees at the bottom right are distracting.', '2007-02-23 15:01:57.000000', NULL, 1),
(3398361, 473579, 58728, '<td valign="top">seems a bit out of focus to me.</td>', 'seems a bit out of focus to me.', '2007-02-23 15:02:12.000000', NULL, 1),
(3398362, 471551, 43774, '<td valign="top">Nice deep colours, composition is very good</td>', 'Nice deep colours, composition is very good', '2007-02-23 15:02:12.000000', NULL, 1),
(3398367, 472883, 43774, '<td valign="top">Love the deep blue sky contrasted with the white snow, excelltent exposure and composition.</td>', 'Love the deep blue sky contrasted with the white snow, excelltent exposure and composition.', '2007-02-23 15:02:37.000000', NULL, 1),
(3398368, 471176, 58728, '<td valign="top">I like the idea....but I personally don''t like the tilt.  I''m sorry.</td>', 'I like the idea....but I personally don''t like the tilt.  I''m sorry.', '2007-02-23 15:02:38.000000', NULL, 1),
(3398371, 473551, 43774, '<td valign="top">Amazing capture, lucky you to have this opportunity for this challenge!</td>', 'Amazing capture, lucky you to have this opportunity for this challenge!', '2007-02-23 15:03:07.000000', NULL, 1),
(3398373, 473545, 43774, '<td valign="top">I really like this, amazing sky and your composition is excellent.</td>', 'I really like this, amazing sky and your composition is excellent.', '2007-02-23 15:03:23.000000', NULL, 1),
(3398381, 471156, 60779, '<td valign="top">First impression and many seconds later, I don''t feel the b&amp;w adds to the image. I think the trees are a little lost in the landscape and I find my eyes are drawn to the bottom &amp; left corner - the darker areas. 5</td>', 'First impression and many seconds later, I don''t feel the b&w adds to the image. I think the trees are a little lost in the landscape and I find my eyes are drawn to the bottom & left corner - the darker areas. 5', '2007-02-23 15:05:54.000000', NULL, 1),
(3398384, 472504, 58728, '<td valign="top">Excellent shot.  I really like the natural frame.</td>', 'Excellent shot.  I really like the natural frame.', '2007-02-23 15:06:07.000000', NULL, 1),
(3398386, 471450, 58728, '<td valign="top">Lovely background color.  Nice dof.</td>', 'Lovely background color.  Nice dof.', '2007-02-23 15:07:24.000000', NULL, 1),
(3398391, 473357, 60779, '<td valign="top">I don''t like the lighting of this picture. It''s too flat in the foreground and blown in the background. On the bark, I see a very narrow dof - too narrow. 4</td>', 'I don''t like the lighting of this picture. It''s too flat in the foreground and blown in the background. On the bark, I see a very narrow dof - too narrow. 4', '2007-02-23 15:08:03.000000', NULL, 1),
(3398392, 473714, 58728, '<td valign="top">Looks a little blurry to me.  The blue sky is nice and vibrant though.</td>', 'Looks a little blurry to me.  The blue sky is nice and vibrant though.', '2007-02-23 15:08:25.000000', NULL, 1),
(3398398, 473341, 58728, '<td valign="top">Lovely..too bad the horizon is a bit tilted...  I think I would have liked it better straight.  Still very pretty nonetheless.</td>', 'Lovely..too bad the horizon is a bit tilted...  I think I would have liked it better straight.  Still very pretty nonetheless.', '2007-02-23 15:09:53.000000', NULL, 1),
(3398399, 473161, 58728, '<td valign="top">Lovely composition and nice rich color.</td>', 'Lovely composition and nice rich color.', '2007-02-23 15:10:46.000000', NULL, 1),
(3398403, 473603, 58728, '<td valign="top">Gorgeous colors.</td>', 'Gorgeous colors.', '2007-02-23 15:12:32.000000', NULL, 1),
(3398407, 470080, 60779, '<td valign="top">Fmy taste, I would have preferred if you''d have placed the sun behind one of the trees and not in the center of the pic. Not bad, not great. 5</td>', 'Fmy taste, I would have preferred if you''d have placed the sun behind one of the trees and not in the center of the pic. Not bad, not great. 5', '2007-02-23 15:14:16.000000', NULL, 1),
(3398414, 473626, 60779, '<td valign="top">Interesting POV but just an OK picture. Nothing stands out to give it an impact. 5</td>', 'Interesting POV but just an OK picture. Nothing stands out to give it an impact. 5', '2007-02-23 15:15:56.000000', NULL, 1),
(3398423, 473288, 60779, '<td valign="top">I like the composition, b&amp;w, textures...but for the challenge I think it misses the mark a bit. I see it as the tire is waiting for someone. having said that..6</td>', 'I like the composition, b&w, textures...but for the challenge I think it misses the mark a bit. I see it as the tire is waiting for someone. having said that..6', '2007-02-23 15:19:29.000000', NULL, 1),
(3398426, 472348, 26633, '<td valign="top">Without the horrid colour cast (sorry if that was intentional!) this would have been in my top three.</td>', 'Without the horrid colour cast (sorry if that was intentional!) this would have been in my top three.', '2007-02-23 15:20:04.000000', NULL, 1),
(3398436, 473579, 60779, '<td valign="top">Not a good picture. Blurry, boring.</td>', 'Not a good picture. Blurry, boring.', '2007-02-23 15:22:05.000000', NULL, 1),
(3398453, 473552, 60779, '<td valign="top">Lighting is big problem for this picture. It''s not a great time of day, and your facing the sun. The composition is too complicated - only the title tells me what you wanted to achieve. But that little branch is dominated by the lake and distracting background tree. 4</td>', 'Lighting is big problem for this picture. It''s not a great time of day, and your facing the sun. The composition is too complicated - only the title tells me what you wanted to achieve. But that little branch is dominated by the lake and distracting background tree. 4', '2007-02-23 15:26:05.000000', NULL, 1),
(3398459, 473666, 74190, '<td valign="top">Great macro work !</td>', 'Great macro work !', '2007-02-23 15:28:21.000000', NULL, 1),
(3398461, 469919, 60779, '<td valign="top">I like the pink tree but it''s lost in the gree one behind it. Top right corner hurts also. The green shrub, tombstones, and barn cut right through the middle of the picture and don''t make for an interesting compostion. 4</td>', 'I like the pink tree but it''s lost in the gree one behind it. Top right corner hurts also. The green shrub, tombstones, and barn cut right through the middle of the picture and don''t make for an interesting compostion. 4', '2007-02-23 15:28:39.000000', NULL, 1),
(3398465, 473655, 51793, '<td valign="top">No, where''s waldo???</td>', 'No, where''s waldo???', '2007-02-23 15:29:49.000000', NULL, 1),
(3398468, 473737, 74190, '<td valign="top">Great pessepctive</td>', 'Great pessepctive', '2007-02-23 15:30:37.000000', NULL, 1),
(3398469, 473341, 51793, '<td valign="top">Well I see someone lives in AU. I can''t wait to see who this belongs too.</td>', 'Well I see someone lives in AU. I can''t wait to see who this belongs too.', '2007-02-23 15:30:37.000000', NULL, 1),
(3398473, 472663, 51793, '<td valign="top">Where is the tree?</td>', 'Where is the tree?', '2007-02-23 15:31:25.000000', NULL, 1),
(3398475, 473517, 60779, '<td valign="top">Couple distracting features: the white, boring sky - which is also dominant in bottom right of pic; the ripples in the water; and the house. Might have been better with vertical composition. 4</td>', 'Couple distracting features: the white, boring sky - which is also dominant in bottom right of pic; the ripples in the water; and the house. Might have been better with vertical composition. 4', '2007-02-23 15:31:36.000000', NULL, 1),
(3398478, 471868, 74190, '<td valign="top">I think a vert shot would have worked better,but still very nice !</td>', 'I think a vert shot would have worked better,but still very nice !', '2007-02-23 15:32:14.000000', NULL, 1),
(3398482, 470909, 74190, '<td valign="top">beautiful !!</td>', 'beautiful !!', '2007-02-23 15:33:10.000000', NULL, 1),
(3398488, 473225, 74190, '<td valign="top">Very nice !! Great lighting for a long exposure.It shows that you took your time to shoot this one.</td>', 'Very nice !! Great lighting for a long exposure.It shows that you took your time to shoot this one.', '2007-02-23 15:34:47.000000', NULL, 1),
(3398492, 473198, 60779, '<td valign="top">Nice one. The whole scene works well. the house in the background adds quite a bit for me. Also I think it''s a big plus that the tree is outside the edges - you''ve composed it so that if fits. 7</td>', 'Nice one. The whole scene works well. the house in the background adds quite a bit for me. Also I think it''s a big plus that the tree is outside the edges - you''ve composed it so that if fits. 7', '2007-02-23 15:35:59.000000', NULL, 1),
(3398499, 473598, 60779, '<td valign="top">Excellent! I''m enjoying staring at it. Thank you. 9</td>', 'Excellent! I''m enjoying staring at it. Thank you. 9', '2007-02-23 15:37:36.000000', NULL, 1),
(3398500, 471865, 29013, '<td valign="top">your focus depth should have been wider/longer to include your subjects in sharp focus</td>', 'your focus depth should have been wider/longer to include your subjects in sharp focus', '2007-02-23 15:37:37.000000', NULL, 1),
(3398501, 473313, 74190, '<td valign="top">Great pic.has an infrared look to it.GOOD JOB !</td>', 'Great pic.has an infrared look to it.GOOD JOB !', '2007-02-23 15:38:01.000000', NULL, 1),
(3398505, 471666, 70514, '<td valign="top">WOW!</td>', 'WOW!', '2007-02-23 15:38:46.000000', NULL, 1),
(3398507, 473436, 74190, '<td valign="top">WOW !!</td>', 'WOW !!', '2007-02-23 15:38:53.000000', NULL, 1),
(3398513, 471307, 60779, '<td valign="top">On this site there are pics I see that I say "just misses." I often can''t put my finger on the exact reason. This is one. I think it''s the contrast that''s subtely distracting to me. 6</td>', 'On this site there are pics I see that I say "just misses." I often can''t put my finger on the exact reason. This is one. I think it''s the contrast that''s subtely distracting to me. 6', '2007-02-23 15:40:40.000000', NULL, 1),
(3398517, 470835, 60779, '<td valign="top">Whatever you''ve done for minimal editing, it worked for me. I like the colors and brightness. The light looks well balanced, and I like the scene. Good luck. 7</td>', 'Whatever you''ve done for minimal editing, it worked for me. I like the colors and brightness. The light looks well balanced, and I like the scene. Good luck. 7', '2007-02-23 15:42:11.000000', NULL, 1),
(3398525, 471176, 26633, '<td valign="top">Sorry, but tilting your camera like that doesn''t add impact or make your picture look "street" or "edgy" or "cool". It makes it look terrible.</td>', 'Sorry, but tilting your camera like that doesn''t add impact or make your picture look "street" or "edgy" or "cool". It makes it look terrible.', '2007-02-23 15:43:43.000000', NULL, 1),
(3398526, 470455, 60779, '<td valign="top">cool perspective (lens)...also the lighting works well. 6</td>', 'cool perspective (lens)...also the lighting works well. 6', '2007-02-23 15:44:06.000000', NULL, 1),
(3398532, 472523, 60779, '<td valign="top">wow...much better big than thumbnail. Neat picture. Great composition, great sky and detail on the trees. 8</td>', 'wow...much better big than thumbnail. Neat picture. Great composition, great sky and detail on the trees. 8', '2007-02-23 15:45:40.000000', NULL, 1),
(3398536, 471043, 26633, '<td valign="top">I think this would look great in black &amp; white instead of brown.</td>', 'I think this would look great in black & white instead of brown.', '2007-02-23 15:46:15.000000', NULL, 1),
(3398540, 473313, 26633, '<td valign="top">I think this would look good in black &amp; white.</td>', 'I think this would look good in black & white.', '2007-02-23 15:47:18.000000', NULL, 1),
(3398550, 473721, 66193, '<td valign="top">absolutely love this one.  perfect. making a favorite.</td>', 'absolutely love this one.  perfect. making a favorite.', '2007-02-23 15:49:36.000000', NULL, 1),
(3398555, 472137, 66193, '<td valign="top">great shot!  love the curving lines of the horizon.</td>', 'great shot!  love the curving lines of the horizon.', '2007-02-23 15:51:06.000000', NULL, 1),
(3398559, 473436, 66193, '<td valign="top">an excellent shot.</td>', 'an excellent shot.', '2007-02-23 15:53:21.000000', NULL, 1),
(3398562, 473025, 60779, '<td valign="top">took me a second but I realized what seems strange here. The color transition from top down to middle works well, but then the bottom is stark white. And in the middle you have a rock and a tree. The image as whole doesn''t suit my eye. 5</td>', 'took me a second but I realized what seems strange here. The color transition from top down to middle works well, but then the bottom is stark white. And in the middle you have a rock and a tree. The image as whole doesn''t suit my eye. 5', '2007-02-23 15:53:34.000000', NULL, 1),
(3398567, 473313, 66193, '<td valign="top">Very nice IR, the 2nd best one in the challenge :) 9</td>', 'Very nice IR, the 2nd best one in the challenge :) 9', '2007-02-23 15:55:11.000000', NULL, 1),
(3398569, 471224, 1993, '<td valign="top">crisp shot - 6</td>', 'crisp shot - 6', '2007-02-23 15:56:04.000000', NULL, 1),
(3398570, 472797, 60779, '<td valign="top">I especially like the ground and background meadow. the tree works well presnented as dark as you have done. I know all horizons aren''t straight, but the leading lines of the foreground hill and background are distracting. 6<br/>edit to add - one of the first pics I saw, then read the rules. Not much you can do about rotating, horizon line. bump to 7.</td>', 'I especially like the ground and background meadow. the tree works well presnented as dark as you have done. I know all horizons aren''t straight, but the leading lines of the foreground hill and background are distracting. 6edit to add - one of the first pics I saw, then read the rules. Not much you can do about rotating, horizon line. bump to 7.', '2007-02-23 15:56:10.000000', NULL, 1),
(3398572, 471921, 60779, '<td valign="top">Nice symmetry of tress. A little later in the day would have given more interesting sky. 5</td>', 'Nice symmetry of tress. A little later in the day would have given more interesting sky. 5', '2007-02-23 15:56:51.000000', NULL, 1),
(3398578, 472815, 60779, '<td valign="top">Nice composition. The main thing that detracts is the lighting. Harsh sunlight. 5</td>', 'Nice composition. The main thing that detracts is the lighting. Harsh sunlight. 5', '2007-02-23 15:57:53.000000', NULL, 1),
(3398579, 470771, 66193, '<td valign="top">really like the colors here.  a little off-balance IMO (too little tree down low, and too much sky up top).</td>', 'really like the colors here.  a little off-balance IMO (too little tree down low, and too much sky up top).', '2007-02-23 15:58:16.000000', NULL, 1),
(3398585, 472690, 1993, '<td valign="top">I like this photo.  Good luck!</td>', 'I like this photo.  Good luck!', '2007-02-23 16:00:29.000000', NULL, 1),
(3398590, 471235, 60779, '<td valign="top">7 - Great capture of the sky''s colors and silhouette of the trees, branches. Personal taste brought it down a point because of the sun. Good luck.</td>', '7 - Great capture of the sky''s colors and silhouette of the trees, branches. Personal taste brought it down a point because of the sun. Good luck.', '2007-02-23 16:02:03.000000', NULL, 1),
(3398593, 471068, 60779, '<td valign="top">Interesting POV, but not an interesting scene. 5</td>', 'Interesting POV, but not an interesting scene. 5', '2007-02-23 16:02:59.000000', NULL, 1),
(3398598, 473225, 60779, '<td valign="top">I like the idea, but I think you exposed a little too long. The stars lose interest when they''re that "streaky" and the tree house is a little bright. Cool tree though. 5</td>', 'I like the idea, but I think you exposed a little too long. The stars lose interest when they''re that "streaky" and the tree house is a little bright. Cool tree though. 5', '2007-02-23 16:04:25.000000', NULL, 1),
(3398600, 473410, 1993, '<td valign="top">It''s a little dark, but I like it.  7</td>', 'It''s a little dark, but I like it.  7', '2007-02-23 16:05:59.000000', NULL, 1),
(3398604, 472471, 66193, '<td valign="top">reminds me of "life" by <a href="//www.dpchallenge.com/profile.php?USER_ID=31947" rel="nofollow" target="_blank">mreza</a></td>', 'reminds me of "life" by mreza', '2007-02-23 16:06:33.000000', NULL, 1),
(3398606, 473643, 66193, '<td valign="top">tree?</td>', 'tree?', '2007-02-23 16:07:21.000000', NULL, 1),
(3398609, 470987, 66193, '<td valign="top">a crop (in camera of course!) right above the foreground shoreline, where the two trees reach upward would have been perfect.</td>', 'a crop (in camera of course!) right above the foreground shoreline, where the two trees reach upward would have been perfect.', '2007-02-23 16:08:25.000000', NULL, 1),
(3398610, 473333, 66193, '<td valign="top">I like the fog, but I would have framed the shot closer into the trees, to remove the distracting guardrail on the right.</td>', 'I like the fog, but I would have framed the shot closer into the trees, to remove the distracting guardrail on the right.', '2007-02-23 16:09:05.000000', NULL, 1),
(3398613, 470341, 60779, '<td valign="top">The really interesting tree is lost in the really un-interesting background. Nice lighting and foreground whispy stuff. 6</td>', 'The really interesting tree is lost in the really un-interesting background. Nice lighting and foreground whispy stuff. 6', '2007-02-23 16:10:52.000000', NULL, 1),
(3398615, 473686, 60779, '<td valign="top">Nice contrast and DOF. 7</td>', 'Nice contrast and DOF. 7', '2007-02-23 16:11:22.000000', NULL, 1),
