(3414271, 473551, 45609, '<td valign="top">Light is very nice, but was it not possible to try another framing or to search for a more spectacular point of view ? This picture seems a bit "sad" to me...</td>', 'Light is very nice, but was it not possible to try another framing or to search for a more spectacular point of view ? This picture seems a bit "sad" to me...', '2007-02-28 14:48:27.000000', NULL, 1),
(3414297, 470146, 45609, '<td valign="top">nice colors and atmosphere</td>', 'nice colors and atmosphere', '2007-02-28 14:55:24.000000', NULL, 1),
(3414372, 471231, 62637, '<td valign="top">This is way too dark.  Is it supposed to be IR?</td>', 'This is way too dark.  Is it supposed to be IR?', '2007-02-28 15:26:23.000000', NULL, 1),
(3414376, 473579, 62637, '<td valign="top">Out of focus and crooked, I get the feeling you shot this out of a moving car.</td>', 'Out of focus and crooked, I get the feeling you shot this out of a moving car.', '2007-02-28 15:27:48.000000', NULL, 1),
