(3414406, 471176, 62637, '<td valign="top">The tilt does nothing for me.  I would prefer to see this horizontal, with less sky.  BW conversion is decent, though.  5</td>', 'The tilt does nothing for me.  I would prefer to see this horizontal, with less sky.  BW conversion is decent, though.  5', '2007-02-28 15:38:37.000000', NULL, 1),
(3414407, 472898, 62637, '<td valign="top">way too dark, but i like the composition.  5</td>', 'way too dark, but i like the composition.  5', '2007-02-28 15:39:06.000000', NULL, 1),
(3414415, 470455, 62637, '<td valign="top">theres something fishy about this one... ;-)</td>', 'theres something fishy about this one... ;-)', '2007-02-28 15:42:27.000000', NULL, 1),
(3414421, 472424, 62637, '<td valign="top">I bet you wish you could have cropped this one...</td>', 'I bet you wish you could have cropped this one...', '2007-02-28 15:44:14.000000', NULL, 1),
