(3414475, 472663, 62637, '<td valign="top">trees?  what, the forest in the distance?</td>', 'trees?  what, the forest in the distance?', '2007-02-28 16:01:32.000000', NULL, 1),
(3414615, 472815, 63398, '<td valign="top">Oh, man! That''s a really terrific setting and tree.</td>', 'Oh, man! That''s a really terrific setting and tree.', '2007-02-28 16:45:20.000000', NULL, 1),
(3414663, 473638, 63398, '<td valign="top">Very peaceful and serene!</td>', 'Very peaceful and serene!', '2007-02-28 16:57:53.000000', NULL, 1),
(3414771, 472471, 13829, '<td valign="top">I totally love the composition, it enhances the message of the picture nicely. The misty atmosphere adds something extra to this shot, too.<br/>Congrats and good luck!</td>', 'I totally love the composition, it enhances the message of the picture nicely. The misty atmosphere adds something extra to this shot, too.Congrats and good luck!', '2007-02-28 17:23:44.000000', NULL, 1),
(3414843, 470835, 63398, '<td valign="top"><b>WOW!!!!!</b> I hate you for this!!!! What a spectacular shot!!!! Just awesome on so many different levels! 9</td>', 'WOW!!!!! I hate you for this!!!! What a spectacular shot!!!! Just awesome on so many different levels! 9', '2007-02-28 17:42:50.000000', NULL, 1),
(3415049, 472867, 73677, '<td valign="top"><b></b>I am very fond of this picture. I think it is the best picture on this competition I have seen. I enjoy looking at this picture!<br/>~Phyllis C.~</td>', 'I am very fond of this picture. I think it is the best picture on this competition I have seen. I enjoy looking at this picture!~Phyllis C.~', '2007-02-28 18:38:34.000000', NULL, 1),
