(3415405, 469919, 52536, '<td valign="top">nice shot.</td>', 'nice shot.', '2007-02-28 20:43:06.000000', NULL, 1),
(3415414, 473571, 43565, '<td valign="top">I love the colors and texture of the sky.</td>', 'I love the colors and texture of the sky.', '2007-02-28 20:46:47.000000', NULL, 1),
(3415416, 473436, 43565, '<td valign="top">This is cool!</td>', 'This is cool!', '2007-02-28 20:47:10.000000', NULL, 1),
(3415480, 473681, 40344, '<td valign="top">I really like this photo particularly the detail contrast between the two trees.</td>', 'I really like this photo particularly the detail contrast between the two trees.', '2007-02-28 21:20:23.000000', NULL, 1),
(3415579, 473721, 66597, '<td valign="top">Stunning, can hardly believe this is straight from camera. You are a very good photographer indeed. Look at those starbursts and color in sky. 10.</td>', 'Stunning, can hardly believe this is straight from camera. You are a very good photographer indeed. Look at those starbursts and color in sky. 10.', '2007-02-28 21:54:36.000000', NULL, 1),
(3415580, 473025, 66597, '<td valign="top">My goodness - I''ve seen this tree before - this is in Wyoming, isn''t it? My grandmother is buried very close to this tree - I almost started crying when I opened the photo.</td>', 'My goodness - I''ve seen this tree before - this is in Wyoming, isn''t it? My grandmother is buried very close to this tree - I almost started crying when I opened the photo.', '2007-02-28 21:54:38.000000', NULL, 1),
(3415584, 473436, 66597, '<td valign="top">Wow, what a bizarre but interesting photo. Can''t believe it is straight from camera; what an incredible shot and use of in-camera techniques.</td>', 'Wow, what a bizarre but interesting photo. Can''t believe it is straight from camera; what an incredible shot and use of in-camera techniques.', '2007-02-28 21:55:31.000000', NULL, 1),
(3415586, 473019, 66597, '<td valign="top">Absolutely beautiful. What a wonderful job with DOF and exposure control.</td>', 'Absolutely beautiful. What a wonderful job with DOF and exposure control.', '2007-02-28 21:55:36.000000', NULL, 1),
(3415588, 470825, 66597, '<td valign="top">Beautiful. What wonderful exposure control and DOF. Refresing to see someone who really knows how to use their camera without editing!</td>', 'Beautiful. What wonderful exposure control and DOF. Refresing to see someone who really knows how to use their camera without editing!', '2007-02-28 21:55:41.000000', NULL, 1),
(3415589, 473467, 66597, '<td valign="top">Lovely exposure control and DOF. This one really needs very little editing! Best of challenge I''ve seen thus far.</td>', 'Lovely exposure control and DOF. This one really needs very little editing! Best of challenge I''ve seen thus far.', '2007-02-28 21:55:48.000000', NULL, 1),
(3415594, 470532, 66597, '<td valign="top">Great leading lines in this! IMO the slightly skewed horizon actually enhances this photo. Glad you weren''t able to correct it :-) 8</td>', 'Great leading lines in this! IMO the slightly skewed horizon actually enhances this photo. Glad you weren''t able to correct it :-) 8', '2007-02-28 21:56:47.000000', NULL, 1),
(3415597, 470386, 66597, '<td valign="top">A unique perspective on this challenge. The ice drop looks wicked, like it could impale someone. Great exposure control. 8.</td>', 'A unique perspective on this challenge. The ice drop looks wicked, like it could impale someone. Great exposure control. 8.', '2007-02-28 21:57:29.000000', NULL, 1),
(3415599, 473059, 66597, '<td valign="top">Beautiful bird and enhancing bokeh. This really needs little or no editing whatsoever. Wonderful job of in-camera control.</td>', 'Beautiful bird and enhancing bokeh. This really needs little or no editing whatsoever. Wonderful job of in-camera control.', '2007-02-28 21:58:05.000000', NULL, 1),
(3415605, 472383, 66597, '<td valign="top">Great exposure - you did a marvelous job of not blowing out those rocks while keeping a nice tint to the sky.</td>', 'Great exposure - you did a marvelous job of not blowing out those rocks while keeping a nice tint to the sky.', '2007-02-28 21:58:55.000000', NULL, 1),
(3415607, 471892, 66597, '<td valign="top">Very, very cool. Love the creativity of this shot!</td>', 'Very, very cool. Love the creativity of this shot!', '2007-02-28 21:59:04.000000', NULL, 1),
(3415609, 473004, 66597, '<td valign="top">Really lovely exposure on this!</td>', 'Really lovely exposure on this!', '2007-02-28 21:59:11.000000', NULL, 1),
(3415611, 472513, 66597, '<td valign="top">Very nice simple, well exposed and well composed shot!</td>', 'Very nice simple, well exposed and well composed shot!', '2007-02-28 21:59:21.000000', NULL, 1),
(3415616, 473551, 66597, '<td valign="top">Wow, guess it was your lucky day, huh? Lovely photo; never see rainbows on DPC, probably because they are so hard to find when you need them. Hope you got a pot of gold as well :-)</td>', 'Wow, guess it was your lucky day, huh? Lovely photo; never see rainbows on DPC, probably because they are so hard to find when you need them. Hope you got a pot of gold as well :-)', '2007-02-28 22:00:24.000000', NULL, 1),
(3415617, 470750, 66597, '<td valign="top">This is lovely! Wonderful job with the abstract effect here. 8.</td>', 'This is lovely! Wonderful job with the abstract effect here. 8.', '2007-02-28 22:00:33.000000', NULL, 1),
(3415628, 472137, 66597, '<td valign="top">This is really superb for straight from camera. Sure, it would be nice to fix the blown celestial object on the left, but you are getting a great score from me for the beautiful stars, motion in the curve of the hill, and great composition with the trees. I also like that you took a risk with 4 trees instead of the magical 3 that is supposed to be used for everything, LOL.</td>', 'This is really superb for straight from camera. Sure, it would be nice to fix the blown celestial object on the left, but you are getting a great score from me for the beautiful stars, motion in the curve of the hill, and great composition with the trees. I also like that you took a risk with 4 trees instead of the magical 3 that is supposed to be used for everything, LOL.', '2007-02-28 22:02:26.000000', NULL, 1),
(3415629, 473717, 66597, '<td valign="top">I like the minimal use of trees here, but they are definitely present. Moody, will probably be underrated. 7 from me.</td>', 'I like the minimal use of trees here, but they are definitely present. Moody, will probably be underrated. 7 from me.', '2007-02-28 22:03:13.000000', NULL, 1),
(3415633, 472999, 66597, '<td valign="top">Really nice exposure control here. Sure, the headstones could use a bit of dodging, but this photo doesn''t suffer from lack of PS. Great job. 7.</td>', 'Really nice exposure control here. Sure, the headstones could use a bit of dodging, but this photo doesn''t suffer from lack of PS. Great job. 7.', '2007-02-28 22:04:01.000000', NULL, 1),
