(3436732, 470750, 57229, '<td valign="top">Oobie congrats well earned. Definitely not a middle of the road shot.</td>', 'Oobie congrats well earned. Definitely not a middle of the road shot.', '2007-03-07 07:14:50.000000', NULL, 0),
(3436824, 470208, 66384, '<td valign="top">Really nice shot. I think I would like it better with the sidewalk cropped off the bottom. Looking forward to seeing your shot for "Red II". It looks like you have plenty of good subjects.</td>', 'Really nice shot. I think I would like it better with the sidewalk cropped off the bottom. Looking forward to seeing your shot for "Red II". It looks like you have plenty of good subjects.', '2007-03-07 07:43:05.000000', NULL, 0),
(3436912, 473341, 67145, '<td valign="top">hey brett ... great shot and congratulations on your pb ... absolutely gorgeous deep sky and great composition ... love the highlights on the opera house .. love the pattern the fence creates ...  it looks processed with those fantastic contrasts .. so well done ..</td>', 'hey brett ... great shot and congratulations on your pb ... absolutely gorgeous deep sky and great composition ... love the highlights on the opera house .. love the pattern the fence creates ...  it looks processed with those fantastic contrasts .. so well done ..', '2007-03-07 08:20:13.000000', NULL, 0),
